215		private buildCustomizedConfig(): AgentConfig {
216			const additionalTools = this.configurationService.getConfig(ConfigKey.PlanAgentAdditionalTools);
217			const isExploreEnabled = this.configurationService.getExperimentBasedConfig(ConfigKey.ExploreAgentEnabled, this.experimentationService);
218			const isSearchSubagentEnabled = this.configurationService.getExperimentBasedConfig(ConfigKey.Advanced.SearchSubagentToolEnabled, this.experimentationService);
219			const coreDefaultModel = this.configurationService.getNonExtensionConfig<string>('chat.planAgent.defaultModel');
220			const modelOverride = coreDefaultModel || this.configurationService.getConfig(ConfigKey.Deprecated.PlanAgentModel);
221	
222			const implementAgentModelOverride = this.configurationService.getConfig(ConfigKey.ImplementAgentModel);
223	
224			// Build handoffs dynamically with model override
225			const startImplementationHandoff: AgentHandoff = {
226				label: 'Start Implementation',
227				agent: 'agent',
228				prompt: 'Start implementation',
229				send: true,
230				...(implementAgentModelOverride ? { model: implementAgentModelOverride } : {})
231			};
232	
233			const openInEditorHandoff: AgentHandoff = {
234				label: 'Open in Editor',
235				agent: 'agent',
236				prompt: '#createFile the plan as is into an untitled file (`untitled:plan-${camelCaseName}.prompt.md` without frontmatter) for further refinement.',
237				showContinueOn: false,
238				send: true
239			};
240	
241			// Collect tools to add
242			const toolsToAdd: string[] = [...additionalTools];
243	
244			// Always include askQuestions tool (now provided by core)
245			toolsToAdd.push('vscode/askQuestions');
246	
247			// When explore agent is enabled, include the 'agent' tool to allow sub-agent calls
248			if (isExploreEnabled) {
249				toolsToAdd.push('agent');
250			}
251	
252			// Merge additional tools (deduplicated)
253			const tools = toolsToAdd.length > 0
254				? [...new Set([...BASE_PLAN_AGENT_CONFIG.tools, ...toolsToAdd])]
255				: [...BASE_PLAN_AGENT_CONFIG.tools];
256	
257			// Start with base config
258			return {
259				...BASE_PLAN_AGENT_CONFIG,
260				// When explore agent is enabled, allow the Explore subagent
261				...(isExploreEnabled ? { agents: ['Explore'] } : {}),
262				tools,
263				handoffs: [startImplementationHandoff, openInEditorHandoff, ...(BASE_PLAN_AGENT_CONFIG.handoffs ?? [])],
264				body: PlanAgentProvider.buildAgentBody(isExploreEnabled, isSearchSubagentEnabled),
265				...(modelOverride ? { model: modelOverride } : {}),
266			};
267		}
